let adminSection='overview';
function editPartnerProfile(id){const r=db.restaurants.find(r=>r.id===id);if(!r)return;modal('Профиль партнёра',`<form class="form" onsubmit="savePartnerProfile(event,'${id}')"><label>Название<input name="name" value="${esc(r.name)}" required maxlength="80"></label><label>Краткое описание<input name="desc" value="${esc(r.desc||'')}" required maxlength="120"></label><label>Адрес в Атырау<input name="address" value="${esc(r.address)}" required maxlength="150"></label><button class="primary">Сохранить</button></form>`)}
async function savePartnerProfile(event,id){event.preventDefault();const r=db.restaurants.find(r=>r.id===id);try{await api(`/api/restaurants/${id}`,'PATCH',{...Object.fromEntries(new FormData(event.target)),cuisines:r.cuisines||[r.type],avg:r.avg});await refreshCatalog();await refreshAccount();$('#modal').close();render();toast('Изменения сохранены')}catch(error){toast(error.message)}}
function deletionDate(r){return new Date(r.deleteAt).toLocaleString('ru-RU',{timeZone:'Asia/Bishkek',dateStyle:'long',timeStyle:'short'})}
function restaurantStatusBadge(r){return r.deleteAt?`<span class="status status-deletion">Удаление запланировано</span><p class="deletion-date">${esc(deletionDate(r))} (Бишкек)</p>`:`<span class="status ${r.status==='inactive'?'status-inactive':''}">${r.status==='inactive'?'Неактивно':'Активно'}</span>`}
function restaurantManagementButtons(r){return `<div class="restaurant-management"><button class="secondary" onclick="newRestaurant('${r.id}')">Редактировать</button>${r.deleteAt?`<button class="quiet" onclick="changeRestaurantLifecycle('${r.id}','cancel-delete')">Отменить удаление</button>`:`<button class="quiet" onclick="changeRestaurantLifecycle('${r.id}','status','${r.status==='inactive'?'active':'inactive'}')">${r.status==='inactive'?'Активировать':'Деактивировать'}</button><button class="delete-restaurant" onclick="confirmRestaurantDeletion('${r.id}')">Удалить через 7 дней</button>`}</div>`}
async function changeRestaurantLifecycle(id,action,status){try{await api(`/api/restaurants/${id}/lifecycle`,'POST',{action,status});await refreshAccount();await refreshCatalog();render();toast(action==='cancel-delete'?'Удаление отменено':'Статус заведения изменён')}catch(error){toast(error.message)}}
function confirmRestaurantDeletion(id){const r=db.restaurants.find(r=>r.id===id);if(!r)return;modal('Удаление заведения',`<h3>${esc(r.name)}</h3><p>Заведение сразу станет неактивным. Через 7 суток будут удалены меню, заказы, бронирования и учётная запись владельца. До этого срока удаление можно отменить в админке.</p><form class="form" onsubmit="submitAuth(event,fields=>scheduleRestaurantDeletion('${id}',fields))"><label>Текущий пароль администратора<input name="password" type="password" required maxlength="128" autocomplete="current-password"></label><div class="form-error" role="alert" hidden></div><button class="primary" type="submit">Подтвердить удаление через 7 дней</button></form>`)}
async function scheduleRestaurantDeletion(id,fields){await api(`/api/restaurants/${id}/lifecycle`,'POST',{action:'schedule-delete',password:fields.password});await refreshAccount();await refreshCatalog();$('#modal').close();render();toast('Удаление запланировано через 7 дней')}
const adminSections=[['overview','Обзор','discover'],['restaurants','Заведения','restaurant'],['certificates','Сертификаты','admin']];
function selectAdminSection(section){if(!adminSections.some(([id])=>id===section))return;adminSection=section;renderAdminWorkspace();scheduleCatalogRefresh()}
function adminMetric(label,value,description,iconName){return `<article class="admin-metric"><span class="metric-icon">${icon(iconName)}</span><span>${label}</span><strong>${value}</strong><small>${description}</small></article>`}
function adminOverview(){const pending=db.restaurants.filter(r=>r.halal?.status==='pending');return `<section class="admin-intro"><div><span class="eyebrow">DAYIN / УПРАВЛЕНИЕ ПЛАТФОРМОЙ</span><h1>Всё под контролем.</h1><p>Подключайте партнёров, управляйте доступом и проверяйте сертификаты.</p><button class="primary" onclick="newRestaurant()">+ Подключить заведение</button></div><div class="intro-symbol" aria-hidden="true">${icon('admin')}<span>DAYIN<br>CONTROL</span></div></section><section class="admin-metrics" aria-label="Показатели платформы">${adminMetric('Заведения',accountData.stats?.restaurants??db.restaurants.length,'Подключены к платформе','restaurant')}${adminMetric('Активные',accountData.stats?.active??db.restaurants.filter(r=>r.status!=='inactive').length,'Доступны в каталоге','restaurant')}${adminMetric('Неактивные',accountData.stats?.inactive??db.restaurants.filter(r=>r.status==='inactive').length,'Отключены от каталога','restaurant')}${adminMetric('Сертификаты',accountData.stats?.pendingCertificates??pending.length,'Ожидают проверки','admin')}</section><div class="admin-overview-grid"><section class="panel"><div class="subheading"><h2>Подключённые заведения</h2><button class="quiet" onclick="selectAdminSection('restaurants')">Все заведения →</button></div>${db.restaurants.length?db.restaurants.slice(0,5).map(r=>`<div class="admin-venue"><span class="venue-symbol">${icon('restaurant')}</span><div><strong>${esc(r.name)}</strong><p>${esc(r.type)} · ${esc(r.address)}</p></div><button class="secondary" onclick="newRestaurant('${r.id}')">Настроить</button></div>`).join(''):'<p>Подключите первое заведение, чтобы начать работу.</p>'}</section><section class="admin-action-card"><span class="eyebrow">ТРЕБУЕТ ВНИМАНИЯ</span><h2>${pending.length?'Проверка сертификатов':'Все проверки завершены'}</h2><p>${pending.length?`Сертификатов халал на проверке: ${pending.length}.`:'Новых сертификатов халал на проверку пока нет.'}</p><button class="secondary" onclick="selectAdminSection('certificates')">Открыть сертификаты →</button></section></div>`}
function adminCertificates(){const venues=db.restaurants.filter(r=>r.halal);return `<div class="admin-page-heading"><div><span class="eyebrow">КОНТРОЛЬ КАЧЕСТВА</span><h1>Сертификаты халал</h1><p>Проверяйте документы и подтверждайте сертификаты заведений.</p></div></div><section class="panel">${venues.length?venues.map(r=>`<article class="admin-certificate"><div><h2>${esc(r.name)}</h2><p>${esc(r.halal.issuer)} · ${esc(r.halal.number)}</p></div>${halalAdminCell(r)}</article>`).join(''):'<div class="empty"><h2>Сертификатов пока нет</h2><p>Документы появятся здесь после отправки владельцем заведения.</p></div>'}</section>${moreRestaurantsButton()}`}
function renderAdminWorkspace(){const section=adminSections.find(([id])=>id===adminSection)||adminSections[0];let content=adminOverview();if(adminSection==='restaurants')content=admin();if(adminSection==='certificates')content=adminCertificates();$('#app').innerHTML=`<div class="admin-shell"><aside class="admin-sidebar"><a class="logo" href="/">dayin<span>.</span></a><span class="admin-label">ПАНЕЛЬ АДМИНИСТРАТОРА</span><nav aria-label="Управление платформой">${adminSections.map(([id,label,i])=>`<button class="${id===adminSection?'active':''}" ${id===adminSection?'aria-current="page"':''} onclick="selectAdminSection('${id}')">${icon(i)}<span>${label}</span>${id==='restaurants'?`<b>${db.restaurants.length}</b>`:''}</button>`).join('')}</nav><a class="admin-catalog-link" href="/">${icon('arrow')}Открыть каталог</a><div class="admin-sidebar-footer">Dayin / Атырау<br><span>Управление ресторанной платформой</span></div></aside><main class="admin-main"><header class="admin-topbar"><div><span class="admin-breadcrumb">Платформа /</span><strong>${section[1]}</strong></div><div class="admin-account">${languageControl()}<span>${icon('admin')} ${esc(authUser.name)}</span><button class="secondary" onclick="logout()">Выйти</button></div></header><div class="admin-content">${content}<footer class="footnote"><span>© 2026 Dayin</span><span>Панель управления</span></footer></div></main></div>`}
